import os
import glob

def task_func(my_list, file_dir='./data_files/', file_ext='.csv'):
    if not isinstance(my_list, list):
        raise TypeError("my_list must be a list")

    my_list.append('12')

    try:
        file_count = sum(int(x) for x in my_list)
    except (TypeError, ValueError):
        file_count = 0

    file_count = max(0, file_count)

    pattern = os.path.join(file_dir, f"*{file_ext}")
    files = sorted(glob.glob(pattern))

    if not files:
        raise FileNotFoundError(f"No CSV files found in directory: {file_dir}")

    selected_files = files[:file_count]

    if not selected_files:
        return pd.DataFrame()

    dataframes = [pd.read_csv(file) for file in selected_files]
    return pd.concat(dataframes, ignore_index=True)

