import pandas as pd
import random
from datetime import datetime

def task_func(
    task_list,
    n_tasks,
    employees=["John Doe", "Jane Smith", "James Brown", "Mary Johnson", "Robert Davis"],
    seed=None,
):
    if n_tasks < 0:
        raise ValueError("n_tasks must be non-negative")

    if seed is not None:
        random.seed(seed)

    columns = ["Task Name", "Assigned To", "Due Date"]

    if n_tasks == 0 or not task_list or not employees:
        return pd.DataFrame(columns=columns)

    due_date = datetime.now().date()
    selected_tasks = random.choices(task_list, k=n_tasks)

    rows = []
    for task in selected_tasks:
        sanitized_task = str(task).replace(" ", "_")
        assigned_to = random.choice(employees)
        rows.append({
            "Task Name": sanitized_task,
            "Assigned To": assigned_to,
            "Due Date": due_date
        })

    return pd.DataFrame(rows, columns=columns)

