import pandas as pd
from datetime import datetime
import random

def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if isinstance(epoch_milliseconds, bool) or not isinstance(epoch_milliseconds, int):
        raise TypeError("epoch_milliseconds must be an integer")

    if epoch_milliseconds < 0:
        raise ValueError("epoch_milliseconds must be non-negative")

    if isinstance(random_seed, bool) or not isinstance(random_seed, int):
        raise TypeError("random_seed must be an integer")

    if not isinstance(products, list) or not all(isinstance(p, str) for p in products):
        raise TypeError("products must be a list of strings")

    if len(products) == 0:
        raise ValueError("products must contain at least one product")

    now = datetime.now()
    current_milliseconds = int(now.timestamp() * 1000)

    if epoch_milliseconds > current_milliseconds:
        raise ValueError("epoch_milliseconds must not be in the future")

    start_datetime = datetime.fromtimestamp(epoch_milliseconds / 1000)
    start_date = start_datetime.date()
    end_date = now.date()

    random.seed(random_seed)

    rows = []
    for day in pd.date_range(start=start_date, end=end_date, freq="D"):
        for product in products:
            rows.append({
                "Product": product,
                "Date": day,
                "Sales": random.randint(10, 50)
            })

    if not rows:
        df = pd.DataFrame(columns=["Product", "Date", "Sales"])
        df["Date"] = pd.DatetimeIndex([])
        df["Sales"] = pd.Series([], dtype="int64")
    else:
        df = pd.DataFrame(rows)
        df["Date"] = pd.to_datetime(df["Date"])
        df["Sales"] = df["Sales"].astype("int64")

    return df

